112: func addRecoveredExportFixtureFacts(t *testing.T, workspace string) string {
113: 	t.Helper()
114: 	artifactEntry := addJournalBackedExportFixtureFacts(t, workspace)
115: 	migrationsDir := testMigrationsDir(t)
116: 	runs, err := workflow.ListRuns(workflow.RunListOptions{WorkspaceRoot: workspace, MigrationsDir: migrationsDir, Status: "active", Limit: 1})
117: 	if err != nil || len(runs) != 1 {
118: 		t.Fatalf("list fixture active Run: %#v, %v", runs, err)
119: 	}
120: 	prior := runs[0]
121: 	observedAt := time.Now().UTC().Add(-time.Second).Format(time.RFC3339Nano)
122: 	observation, err := workflow.ObserveRun(workflow.RunOptions{WorkspaceRoot: workspace, MigrationsDir: migrationsDir, ActorID: "actor-harness", IdempotencyKey: "fixture-run-observe"}, workflow.RunObserveRequest{RunID: prior.ID, ExpectedVersion: prior.Version, Liveness: workflow.Liveness{ExecutorID: prior.Executor.ID, State: "terminated", SourceRef: "fixture:terminated", ObservedAt: observedAt}})
123: 	if err != nil {
124: 		t.Fatalf("observe fixture Run termination: %v", err)
125: 	}
126: 	claimVersion := fixtureClaimVersion(t, workspace, prior.ClaimID)
127: 	if _, err := claims.ReleaseGeneric(claims.MutationOptions{WorkspaceRoot: workspace, MigrationsDir: migrationsDir, ActorID: "actor-builder", IdempotencyKey: "fixture-claim-release"}, claims.ReleaseRequest{ClaimID: prior.ClaimID, ExpectedVersion: claimVersion, Reason: "operator-released"}); err != nil {
128: 		t.Fatalf("release fixture predecessor Claim: %v", err)
129: 	}
130: 	inspection, err := workflow.InspectRun(workspace, migrationsDir, prior.ID, workspace)
131: 	if err != nil {
132: 		t.Fatalf("inspect fixture Run for recovery: %v", err)
133: 	}
134: 	if _, err := workflow.RecoverRun(workflow.RunOptions{WorkspaceRoot: workspace, MigrationsDir: migrationsDir, ActorID: "actor-builder", IdempotencyKey: "fixture-run-recover"}, workflow.RunRecoveryRequest{PriorRunID: prior.ID, ExpectedRunVersion: observation.Run.Version, ExpectedClaimVersion: claimVersion + 1, ObservationID: observation.Observation.ID, ReconciliationDigest: inspection.Reconciliation.Digest, AdoptedPaths: []string{"fixture-artifact.txt"}, Authority: workflow.RecoveryAuthority{Mode: "ordinary", ActorID: "actor-builder", Reason: "trusted termination"}, Executor: workflow.Executor{ID: "executor-recovered", Source: "activated-harness"}, TTLSeconds: 60}); err != nil {
135: 		t.Fatalf("recover fixture Run: %v", err)
136: 	}
137: 	return artifactEntry
138: }
